; sprites.asm — Colony sim, Amstrad CPC Mode 0
; ΠΑΡΑΓΕΤΑΙ ΑΥΤΟΜΑΤΑ από tools/make_sprites.py — μην το επεξεργάζεσαι με το χέρι.
;
; Δεδομένα γραμμικά (γραμμή-γραμμή), ΟΧΙ στη διάταξη της μνήμης οθόνης.
;
; Θόλοι, δακτύλιοι, διάδρομοι και σημεία σύνδεσης έχουν ΜΑΣΚΑ, σε μορφή
; «mask, data, mask, data...» ανά γραμμή:
;       ld a,(hl) : inc hl : and (de) : ld b,a
;       ld a,(hl) : inc hl : or b     : ld (de),a : inc de
; Τα εικονίδια και τα επικαλύμματα πληρότητας είναι αδιαφανή (μόνο data).
;
; Φόρτωσε το μπλοκ σε διεύθυνση πολλαπλάσιο του 256 (το flip_mode0 θέλει σελίδα).

DOME_S_D    equ 48        ; οπτική διάμετρος
DOME_S_W    equ 8         ; bytes ανά γραμμή τεταρτημορίου
DOME_S_H    equ 32        ; γραμμές τεταρτημορίου
DOME_S_SZ   equ 512       ; bytes ανά τεταρτημόριο (mask+data)
DOME_M_D    equ 80        ; οπτική διάμετρος
DOME_M_W    equ 12        ; bytes ανά γραμμή τεταρτημορίου
DOME_M_H    equ 48        ; γραμμές τεταρτημορίου
DOME_M_SZ   equ 1152      ; bytes ανά τεταρτημόριο (mask+data)
DOME_L_D    equ 112       ; οπτική διάμετρος
DOME_L_W    equ 16        ; bytes ανά γραμμή τεταρτημορίου
DOME_L_H    equ 64        ; γραμμές τεταρτημορίου
DOME_L_SZ   equ 2048      ; bytes ανά τεταρτημόριο (mask+data)

ICON_W      equ 4
ICON_H      equ 8
ICON_SIZE   equ 32          ; room_icons + type*ICON_SIZE
OCC_W       equ 6
OCC_H       equ 16
OCC_SIZE    equ 96          ; occupancy + level*OCC_SIZE
OCC_LEVELS  equ 5
            ; οι θέσεις εικονιδίου/πληρότητας είναι στο interior_ofs

CORR_H_W    equ 4
CORR_H_H    equ 8
CORR_V_W    equ 2
CORR_V_H    equ 16
CORR_D_W    equ 8           ; διαγώνιο tile
CORR_D_H    equ 16
CORR_D_SX   equ 4           ; βήμα τοποθέτησης σε bytes
CORR_D_SY   equ 16
MACH_W      equ 4
MACH_H      equ 12
MACH_SIZE   equ 48          ; machines + type*MACH_SIZE
MACH_TYPES  equ 7           ; oxygen, iron, bioplastic, weapons, processors, robots, food
MACH_SLOTS  equ 8           ; θέσεις ανά μέγεθος στον πίνακα

CONN_W      equ 2
CONN_H      equ 8
CONN_DIRS   equ 8           ; n,ne,e,se,s,sw,w,nw


